import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val a = IntArray(110)
    var i = 1
    var currentN = n
    while (true) {
        if (currentN == 1) break
        val yushu = currentN % 2
        currentN /= 2
        a[i] = yushu
        if (currentN == 1) {
            i++
            break
        }
        i++
    }
    print(i)
    i--
    for (j in i downTo 0) {
        if (a[j] == 1) print(" $j")
    }
    println()
}

