import java.io.*

fun main() {
    val n = readln().toIntOrNull() ?: 0
    val a = IntArray(110)
    var i = 1
    var num = n
    while (true) {
        if (num == 1) break
        val yushu = num % 2
        num /= 2
        a[i] = yushu
        if (num == 1) {
            i++
            break
        }
        i++
    }
    val sb = StringBuilder()
    sb.append(i)
    i--
    while (i >= 0) {
        if (a[i] != 0) {
            sb.append(" ").append(i)
        }
        i--
    }
    sb.append("\n")
    print(sb)
}

