fun main() {
    val n = readln().toInt()
    if (n == 1) {
        println(1)
        return
    }
    val bits = mutableListOf<Int>()
    var num = n
    while (true) {
        if (num == 1) break
        bits.add(num % 2)
        num /= 2
        if (num == 1) break
    }
    val bitLength = bits.size + 1
    val sb = StringBuilder().apply {
        append(bitLength)
        for (i in bits.lastIndex downTo 0) {
            if (bits[i] == 1) append(" ${i + 1}")
        }
    }
    println(sb)
}
